"""Essential Adapter tests with small synthetic inputs; no real-data metrics."""
# Test functions are generated by GPT 6.1 sol
import joblib
import numpy as np
import pytest
from sklearn.linear_model import Ridge

from ridge.models.sklearn_adapter import SklearnAdapter


def _sample_data():
    rng = np.random.default_rng(42)
    X = np.eye(4, dtype=np.float32)[rng.integers(0, 4, size=(64, 4))]
    y = 5 + 2 * X[:, 0, 0] - 3 * X[:, 2, 3] + 0.5 * X[:, 3, 1]
    return X, y


def test_flatten_fit_and_predict():
    X = np.zeros((3, 50, 4), dtype=np.float32)
    X[0, 0, 0], X[1, 1, 2], X[2, 49, 3] = 1, 2, 3
    expected_flat = np.zeros((3, 200), dtype=np.float32)
    expected_flat[0, 0], expected_flat[1, 6], expected_flat[2, 199] = 1, 2, 3
    y = np.array([1.0, 2.0, 4.0])
    reference = Ridge().fit(expected_flat, y)
    model = SklearnAdapter(Ridge())

    assert model.fit(X, y) is model
    assert model.estimator.n_features_in_ == 200
    np.testing.assert_allclose(model.estimator.coef_, reference.coef_)
    coefficients = model.estimator.coef_.copy()
    intercept = model.estimator.intercept_
    predictions = model.predict(X[[2, 0, 1]])
    assert predictions.shape == (3,)
    assert np.isfinite(predictions).all()
    np.testing.assert_allclose(predictions, reference.predict(expected_flat[[2, 0, 1]]))
    assert model.predict(X[:1]).shape == (1,)
    np.testing.assert_array_equal(model.estimator.coef_, coefficients)
    assert model.estimator.intercept_ == intercept


def test_ridge_learns_an_additive_signal():
    X, y = _sample_data()
    model = SklearnAdapter(Ridge(alpha=0.01), sequence_length=4)
    model.fit(X[:48], y[:48])
    model_error = np.mean((model.predict(X[48:]) - y[48:]) ** 2)
    baseline_error = np.mean((y[:48].mean() - y[48:]) ** 2)
    assert model_error < baseline_error


def test_validation_is_checked_but_not_used_for_training():
    X, y = _sample_data()
    model = SklearnAdapter(Ridge(), sequence_length=4)
    with pytest.raises(ValueError, match="together"):
        model.fit(X, y, X_val=X)
    with pytest.raises(ValueError, match="together"):
        model.fit(X, y, y_val=y)
    with pytest.raises(ValueError, match="y_val"):
        model.fit(X, y, X_val=X, y_val=y[:-1])

    reference = Ridge().fit(X[:48].reshape(48, 16), y[:48])
    model.fit(X[:48], y[:48], X_val=X[48:], y_val=np.full(16, 1_000_000.0))
    np.testing.assert_allclose(model.estimator.coef_, reference.coef_)
    np.testing.assert_allclose(model.estimator.intercept_, reference.intercept_)
    assert model.estimator.alpha == 1.0
    model.fit(X[:48], y[:48], X_val=X[:0], y_val=y[:0])
    np.testing.assert_allclose(model.estimator.coef_, reference.coef_)


def test_input_shape_and_single_target():
    X, y = _sample_data()
    model = SklearnAdapter(Ridge(), sequence_length=4)
    with pytest.raises(ValueError, match="X must have shape"):
        model.fit(X.reshape(64, 16), y)
    with pytest.raises(ValueError, match="y must have shape"):
        model.fit(X, y[:, None])


def test_save_load_and_config(tmp_path):
    X, y = _sample_data()
    estimator = Ridge(alpha=np.float32(0.1), max_iter=np.int64(1000))
    model = SklearnAdapter(estimator, sequence_length=4).fit(X, y)
    config = model.get_config()

    path = tmp_path / "nested" / "ridge.joblib"
    model.save(path)
    restored = SklearnAdapter.load(path)
    np.testing.assert_allclose(restored.predict(X), model.predict(X))
    assert restored.get_config() == config
    package = joblib.load(path)
    assert package["schema_version"] == 1
    assert package["base_order"] == "ACGT"
    assert package["flatten_order"] == "C"
    assert package["target_unit"] == "MRL"
    assert {"python", "numpy", "scikit-learn", "joblib"} <= package["software_versions"].keys()


def test_load_rejects_incompatible_metadata(tmp_path):
    X, y = _sample_data()
    path = tmp_path / "ridge.joblib"
    SklearnAdapter(Ridge(), sequence_length=4).fit(X, y).save(path)
    package = joblib.load(path)

    package["schema_version"] = 999
    joblib.dump(package, path)
    with pytest.raises(ValueError, match="schema"):
        SklearnAdapter.load(path)

    package["schema_version"], package["flatten_order"] = 1, "F"
    joblib.dump(package, path)
    with pytest.raises(ValueError, match="feature conventions"):
        SklearnAdapter.load(path)

    package["flatten_order"], package["sequence_length"] = "C", 5
    joblib.dump(package, path)
    with pytest.raises(ValueError, match="feature count"):
        SklearnAdapter.load(path)
